package com.bluepay.views;

import com.bluepay.main.BluePayApp;import com.bluepay.models.*;import com.bluepay.services.*;import com.bluepay.utils.*;import javafx.geometry.*;import javafx.scene.Scene;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.FileChooser;import java.io.File;import java.nio.file.Path;import java.util.*;
import com.google.zxing.*;import com.google.zxing.client.j2se.BufferedImageLuminanceSource;import com.google.zxing.common.HybridBinarizer;import javax.imageio.ImageIO;

public class DashboardView extends BaseView {
 private final AuthenticationService auth;private final PaymentService pay;private final AccountService accounts;private final ReceiptGenerator receipts=new ReceiptGenerator();private BorderPane root;private VBox content;private Label balanceLabel; private String qrRecipient, qrUpi, qrAmount;
 public DashboardView(BluePayApp a,AuthenticationService au,PaymentService p,AccountService ac){super(a);auth=au;pay=p;accounts=ac;}
 public Scene build(){protect();root=new BorderPane();root.setStyle("-fx-background-color:#080D18;");root.setLeft(sidebar());root.setCenter(mainArea());root.setBottom(bottomNav());show("Home");return new Scene(root,1180,780);}
 private VBox sidebar(){VBox side=new VBox(12);side.setPadding(new Insets(25,17,20,17));side.setPrefWidth(215);side.setStyle("-fx-background-color:#0B1422;-fx-border-color:transparent #1B2A40 transparent transparent;");Label logo=new Label("◆  BLUEPAY");logo.setStyle("-fx-text-fill:white;-fx-font-size:21px;-fx-font-weight:900;");side.getChildren().addAll(logo,Ui.label("PAYMENT WORKSPACE"));for(String s:List.of("Home","Send Money","Scan & Pay","History","Bank Accounts","Recharge & Bills","Rewards","Profile & Settings")){Button b=Ui.ghost(s);b.setAlignment(Pos.CENTER_LEFT);b.setOnAction(e->show(s));side.getChildren().add(b);}Region spacer=new Region();VBox.setVgrow(spacer,Priority.ALWAYS);Button logout=Ui.ghost("⇥  Logout");logout.setOnAction(e->app.logout());side.getChildren().addAll(spacer,Ui.label("● DEMO SYSTEM ONLINE"),logout);return side;}
 private VBox mainArea(){VBox box=new VBox(18);box.setPadding(new Insets(27));ScrollPane sc=new ScrollPane(box);sc.setFitToWidth(true);sc.setStyle("-fx-background:#080D18;-fx-background-color:#080D18;");content=box;return new VBox(sc);}
 private HBox bottomNav(){HBox h=new HBox(8);h.setAlignment(Pos.CENTER);h.setPadding(new Insets(8));h.setStyle("-fx-background-color:#0D1726;-fx-border-color:#1B2A40 transparent transparent transparent;");for(String s:List.of("Home","History","Rewards","Profile & Settings")){Button b=Ui.ghost(s);b.setOnAction(e->show(s));h.getChildren().add(b);}return h;}
 private void header(String title,String sub){HBox h=new HBox();VBox v=new VBox(5,Ui.title(title),Ui.label(sub));Label avatar=new Label(SessionManager.getInstance().getUser().fullName().substring(0,1).toUpperCase());avatar.setStyle("-fx-background-color:#17457B;-fx-text-fill:white;-fx-padding:12;-fx-background-radius:30;-fx-font-weight:bold;");Region r=new Region();HBox.setHgrow(r,Priority.ALWAYS);h.getChildren().addAll(v,r,avatar);content.getChildren().add(h);}
 private void show(String page){protect();content.getChildren().clear();switch(page){case "Home"->home();case "Send Money"->send();case "Scan & Pay"->scan();case "History"->history();case "Bank Accounts"->bankAccounts();case "Recharge & Bills"->recharge();case "Rewards"->rewards();case "Profile & Settings"->profile();default->home();}}
 private void home(){User u=SessionManager.getInstance().getUser();header("Good day, "+u.fullName().split(" ")[0]+" 👋","Here is your BLUEPAY account overview.");balanceLabel=new Label("₹"+String.format("%,.2f",pay.balance()));balanceLabel.setStyle("-fx-text-fill:white;-fx-font-size:34px;-fx-font-weight:900;");VBox wallet=Ui.card(Ui.label("AVAILABLE DEMO WALLET BALANCE"),balanceLabel,Ui.label("Fictional funds • No real bank connection"));wallet.setStyle("-fx-background-color:linear-gradient(to right,#0B65C8,#243FBD);-fx-background-radius:18;");HBox quick=new HBox(12);for(String s:List.of("↗ Send Money","▦ Scan & Pay","＋ Add Demo Funds","▤ Check Balance")){Button b=Ui.ghost(s);b.setOnAction(e->{if(s.contains("Send"))show("Send Money");else if(s.contains("Scan"))show("Scan & Pay");else if(s.contains("Add"))addFunds();else Ui.info("Available demo balance: "+money(pay.balance()));});quick.getChildren().add(b);}HBox cards=new HBox(12,Ui.card(Ui.label("TODAY'S SPENDING"),Ui.title(money(pay.dailySpent()))),Ui.card(Ui.label("DAILY LIMIT"),Ui.title("₹10,000")),Ui.card(Ui.label("LINKED ACCOUNTS"),Ui.title(String.valueOf(accounts.all().size()))));content.getChildren().addAll(wallet,quick,cards,Ui.title("Recent Transactions"));List<Transaction> tx=pay.history("","ALL");for(Transaction t:tx.stream().limit(5).toList())content.getChildren().add(txRow(t));}
 private String money(double n){return "₹"+String.format("%,.2f",n);}
 private VBox txRow(Transaction t){HBox h=new HBox(12);h.setAlignment(Pos.CENTER_LEFT);Label icon=new Label("↗");icon.setStyle("-fx-background-color:#17375C;-fx-text-fill:#72B8FF;-fx-padding:12;-fx-background-radius:30;");VBox details=new VBox(4,Ui.value(t.recipient()),Ui.label(t.upiId()+" • "+t.createdAt()));Region r=new Region();HBox.setHgrow(r,Priority.ALWAYS);VBox amount=new VBox(4,Ui.value("-"+money(t.amount())),Ui.label(t.status()));h.getChildren().addAll(icon,details,r,amount);VBox card=Ui.card(h);return card;}
 private void send(){header("Send Money","Transfer virtual demo funds to another demo UPI ID.");TextField name=Ui.field("Recipient name"),upi=Ui.field("recipient@bluepay"),amount=Ui.field("Amount in ₹"),note=Ui.field("Payment note (optional)");if(qrRecipient!=null){name.setText(qrRecipient);upi.setText(qrUpi);if(qrAmount!=null)amount.setText(qrAmount);qrRecipient=null;qrUpi=null;qrAmount=null;}ComboBox<String> contacts=new ComboBox<>();contacts.getItems().addAll("Demo contact — alex@bluepay","Demo contact — priya@bluepay");contacts.setPromptText("Choose a saved demo contact");contacts.setMaxWidth(Double.MAX_VALUE);contacts.setOnAction(e->{String v=contacts.getValue();if(v!=null){String[] p=v.split("—");name.setText(p[0].replace("Demo contact","").trim());upi.setText(p[1].trim());}});Button payBtn=Ui.button("Continue to payment confirmation");payBtn.setOnAction(e->{try{if(!amount.getText().matches("\\d+(\\.\\d{1,2})?"))throw new IllegalArgumentException("Enter a valid amount.");double a=Double.parseDouble(amount.getText());if(a<=0||a>10000)throw new IllegalArgumentException("Amount must be between ₹1 and ₹10,000.");if(a>pay.balance())throw new IllegalArgumentException("Insufficient demo balance.");if(pay.dailySpent()+a>10000)throw new IllegalArgumentException("Daily limit exceeded.");TextInputDialog pin=new TextInputDialog();pin.setTitle("Demo UPI PIN");pin.setHeaderText("Confirm "+money(a)+" to "+name.getText());pin.setContentText("Enter demo UPI PIN (default 1234):");String entered=pin.showAndWait().orElse("");Transaction t=pay.pay(name.getText(),upi.getText(),a,note.getText(),"TRANSFER",entered);Ui.info("Payment successful!\nTransaction ID: "+t.txnId()+"\nRecipient: "+t.recipient()+"\nAmount: "+money(t.amount()));if(Ui.confirm("Download payment receipt as PDF?"))saveReceipt(t);show("Home");}catch(Exception ex){Ui.error(ex.getMessage());}});content.getChildren().add(Ui.card(Ui.label("SAVED CONTACT"),contacts,Ui.label("RECIPIENT NAME"),name,Ui.label("RECIPIENT UPI ID"),upi,Ui.label("AMOUNT"),amount,Ui.label("DESCRIPTION"),note,payBtn));}
 private void scan(){header("Scan & Pay","Upload a QR image to decode a BLUEPAY-compatible demo payment QR.");Button upload=Ui.button("Upload QR image");Label decoded=Ui.value("No QR image selected.");TextField amount=Ui.field("Enter amount in ₹");Button continueBtn=Ui.button("Continue to payment");String[] target=new String[2];upload.setOnAction(e->{FileChooser fc=new FileChooser();fc.setTitle("Choose QR image");fc.getExtensionFilters().add(new FileChooser.ExtensionFilter("Image files","*.png","*.jpg","*.jpeg","*.bmp"));File f=fc.showOpenDialog(root.getScene().getWindow());if(f!=null)try{var image=ImageIO.read(f);var source=new BufferedImageLuminanceSource(image);String raw=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(source))).getText();if(!raw.startsWith("upi://pay?"))throw new IllegalArgumentException("Only BLUEPAY demo UPI QR payloads are supported.");Map<String,String> m=new HashMap<>();for(String part:raw.substring(raw.indexOf('?')+1).split("&")){String[] kv=part.split("=",2);if(kv.length==2)m.put(kv[0],java.net.URLDecoder.decode(kv[1],java.nio.charset.StandardCharsets.UTF_8));}target[0]=m.get("pn");target[1]=m.get("pa");if(target[0]==null||target[1]==null)throw new IllegalArgumentException("QR must contain pn and pa fields.");decoded.setText("Recipient: "+target[0]+" • "+target[1]);if(m.containsKey("am"))amount.setText(m.get("am"));}catch(Exception ex){Ui.error("Could not decode supported demo QR: "+ex.getMessage());}});continueBtn.setOnAction(e->{if(target[0]==null){Ui.error("Upload a valid demo QR first.");return;}qrRecipient=target[0];qrUpi=target[1];qrAmount=amount.getText();show("Send Money");});content.getChildren().add(Ui.card(upload,decoded,Ui.label("PAYMENT AMOUNT"),amount,continueBtn,Ui.label("Demo QR example: upi://pay?pa=alex@bluepay&pn=Alex&am=250")));}
 private void history(){header("Transaction History","Search and review saved demo transactions.");TextField search=Ui.field("Search recipient, UPI ID or transaction ID");ComboBox<String> status=new ComboBox<>();status.getItems().addAll("ALL","SUCCESS","FAILED");status.setValue("ALL");VBox list=new VBox(9);Runnable refresh=()->{list.getChildren().clear();for(Transaction t:pay.history(search.getText(),status.getValue())){Button row=Ui.ghost(t.recipient()+"  •  "+money(t.amount())+"  •  "+t.status()+"  •  "+t.txnId());row.setOnAction(e->{if(Ui.confirm("Export receipt for "+t.txnId()+"?"))saveReceipt(t);});list.getChildren().add(row);}};search.textProperty().addListener((o,a,b)->refresh.run());status.setOnAction(e->refresh.run());refresh.run();content.getChildren().addAll(Ui.card(search,status,list));}
 private void bankAccounts(){header("Bank Accounts","Manage fictional bank profiles used by this simulator.");VBox list=new VBox(10);Runnable refresh=()->{list.getChildren().clear();for(String[] a:accounts.all()){HBox row=new HBox(10);row.setAlignment(Pos.CENTER_LEFT);VBox info=new VBox(4,Ui.value(a[1]),Ui.label(a[2]+" • "+a[3]));Region r=new Region();HBox.setHgrow(r,Priority.ALWAYS);Button primary=Ui.ghost(Integer.parseInt(a[4])==1?"PRIMARY":"Set primary");primary.setOnAction(e->{accounts.primary(Long.parseLong(a[0]));bankAccounts();});Button remove=Ui.ghost("Remove");remove.setOnAction(e->{if(Ui.confirm("Remove this demo account?")){accounts.remove(Long.parseLong(a[0]));bankAccounts();}});row.getChildren().addAll(info,r,primary,remove);list.getChildren().add(Ui.card(row));}};refresh.run();TextField bank=Ui.field("Fictional bank name"),last=Ui.field("Last 4 fictional digits");Button add=Ui.button("Add demo bank account");add.setOnAction(e->{try{accounts.add(bank.getText(),last.getText());bankAccounts();}catch(Exception ex){Ui.error(ex.getMessage());}});content.getChildren().addAll(list,Ui.card(Ui.title("Add demo account"),bank,last,add));}
 private void recharge(){header("Recharge & Bills","Simulate common utility and recharge payments.");ComboBox<String> type=new ComboBox<>();type.getItems().addAll("Mobile Recharge","Electricity","Water","Broadband","DTH","Gas");type.setValue("Mobile Recharge");TextField consumer=Ui.field("Mobile number / consumer ID"),provider=Ui.field("Operator / provider"),amount=Ui.field("Amount in ₹");Button submit=Ui.button("Continue to demo payment");submit.setOnAction(e->{try{if(consumer.getText().isBlank()||provider.getText().isBlank())throw new IllegalArgumentException("Enter consumer ID and provider.");double a=Double.parseDouble(amount.getText());TextInputDialog d=new TextInputDialog();d.setHeaderText("Demo PIN to pay "+money(a));d.setContentText("Enter demo PIN:");Transaction t=pay.pay(provider.getText(),consumer.getText()+"@bill.bluepay",a,type.getValue(),"BILL",d.showAndWait().orElse(""));Ui.info(type.getValue()+" payment simulated successfully.\n"+t.txnId());show("Home");}catch(Exception ex){Ui.error(ex.getMessage());}});content.getChildren().add(Ui.card(Ui.label("SERVICE TYPE"),type,Ui.label("CONSUMER ID"),consumer,Ui.label("OPERATOR / PROVIDER"),provider,Ui.label("AMOUNT"),amount,submit));}
 private void rewards(){header("Rewards","Demo rewards and activity.");content.getChildren().add(Ui.card(Ui.title("BLUEPOINTS"),Ui.title("120 points"),Ui.label("You are viewing sample educational reward points. No cash value."),Ui.label("Complete simulated transactions to explore the app.")));}
 private void profile(){User u=SessionManager.getInstance().getUser();header("Profile & Settings","Manage your local demo profile and security preferences.");TextField name=Ui.field(u.fullName()),email=Ui.field(u.email());Button save=Ui.button("Save profile changes");save.setOnAction(e->{if(name.getText().isBlank()||!email.getText().contains("@")){Ui.error("Enter a valid name and email.");return;}try(var c=com.bluepay.database.DatabaseConnection.getConnection();var p=c.prepareStatement("UPDATE users SET full_name=?,email=? WHERE id=?")){p.setString(1,name.getText());p.setString(2,email.getText());p.setLong(3,u.id());p.executeUpdate();Ui.info("Profile updated. Log in again to refresh the displayed name.");}catch(Exception ex){Ui.error(ex.getMessage());}});PasswordField old=Ui.password("Current password"),np=Ui.password("New password");Button change=Ui.ghost("Change password");change.setOnAction(e->{try{auth.changePassword(old.getText(),np.getText());Ui.info("Password updated.");}catch(Exception ex){Ui.error(ex.getMessage());}});PasswordField pin=Ui.password("New 4-digit demo PIN");Button pinSave=Ui.ghost("Update demo PIN");pinSave.setOnAction(e->{try{pay.updatePin(pin.getText());Ui.info("Demo PIN updated.");}catch(Exception ex){Ui.error(ex.getMessage());}});Button logout=Ui.button("Logout");logout.setOnAction(e->app.logout());content.getChildren().addAll(Ui.card(Ui.title("Personal information"),Ui.label("Full name"),name,Ui.label("Email"),email,save),Ui.card(Ui.title("Security settings"),old,np,change,pin,pinSave),Ui.card(Ui.title("About BLUEPAY"),Ui.label("JavaFX • SQLite • Java 17+"),Ui.label("Educational simulator only. No real payments."),logout));}
 private void addFunds(){TextInputDialog d=new TextInputDialog("1000");d.setHeaderText("Add virtual funds to demo wallet");d.setContentText("Amount (₹):");d.showAndWait().ifPresent(v->{try{pay.addDemoFunds(Double.parseDouble(v));show("Home");}catch(Exception ex){Ui.error(ex.getMessage());}});}
 private void saveReceipt(Transaction t){try{FileChooser fc=new FileChooser();fc.setInitialFileName("BLUEPAY-"+t.txnId()+".pdf");fc.getExtensionFilters().add(new FileChooser.ExtensionFilter("PDF receipt","*.pdf"));File f=fc.showSaveDialog(root.getScene().getWindow());if(f!=null){new ReceiptGenerator().generate(t,Path.of(f.toURI()));Ui.info("Receipt saved to "+f);}}catch(Exception ex){Ui.error("Receipt export failed: "+ex.getMessage());}}
}